"""Computes the next material index with respect to default avatar skin indices.

    Args:
        mtl (int): The current material index.

    Returns:
        int: The next material index to be used.
    """
def skip_material(mtl: int) -> int {
    if ((mtl == 1) or (mtl == 6)) {
        return (mtl + 2);
    }
    return (mtl + 1);
}

"""intersection of two lists
    """
def intersect(lst1: Any, lst2: Any) -> object {
    lst3 = [
        value
        for value in lst1
        if (value in lst2)
    ];
    return lst3;
}

"""reverse reverses the items in a list of items

	Parameters:

	     items: list of items (can be a string)

	"""
def reverse(items: Any) -> object {
    reverseList = [];
    itemSize = len(items);
    for i in range(itemSize, 0, -1) {
        reverseList.append(items[(i - 1)]);
    }
    return reverseList;
}

